mapper.select:
select * from( SELECT DISTINCT od.device_code, m.id, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.device_status, m.manufacturer_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'horn_manage_status' AND DICT_VALUE = m.device_status limit 1) deviceStatusName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'broadcast_manufacturer' AND DICT_VALUE = m.manufacturer_code limit 1) manufacturerName, m.model_code, m.device_type, m.site_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'broadcast_device_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, m.height, m.longitude, m.latitude, m.location, m.access_node,
CAST(ST_DISTANCE(POINT(#{param.longitude},#{param.latitude}),POINT(m.longitude,m.latitude))*111195 as DECIMAL(65,2)) as distance,
(CASE WHEN od.ord_status in ('0','1','2') THEN '1' WHEN od.ord_status = '3' THEN '3' WHEN od.ord_status = '4' THEN '4' END ) orderStatus, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, od.tenant_id as tenantId, pro.area_name as provinceName, pro.area_code as province_code, city.area_name as cityName, city.area_code as city_code, county.area_name as countyName, county.area_code as county_code, town.area_code as town_code, town.area_name as town_name from vm_order_horn_devices od LEFT JOIN vm_horn_device_info_t m on m.device_code = od.device_code LEFT JOIN vm_tenant_device_common_rel_t ten on ten.device_code = od.device_code and ten.tenant_id = od.tenant_id and ten.industry_code = od.industry_code and ten.delete_flag = 0 and ten.device_type = 2 LEFT JOIN sys_area pro on pro.area_code = m.province_code LEFT JOIN sys_area city on city.area_code = m.city_code LEFT JOIN sys_area county on county.area_code = m.county_code LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code and dct.coll_obj_type = '10' AND dct.user_id = #{param.userId}
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = m.device_code and vod.delete_flag = '0' and vod.tenant_id = od.tenant_id and vod.industry_code = od.industry_code and vod.device_type = 12
where od.delete_flag = 0 and m.delete_flag = 0 and od.tenant_id = #{param.tenantId}
and vod.dept_id in
#{id}
and dct.user_device_coll_id IS NOT NULL
and m.device_status in
#{status}
and m.manufacturer_code in
#{manufacturerCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_code in
#{item}
AND m.province_code = #{param.provinceCode}
AND m.city_code = #{param.cityCode}
AND m.county_code = #{param.countyCode}
AND m.town_code = #{param.townCode}
and m.device_status = #{param.deviceStatus}
and m.manufacturer_code like CONCAT('%', #{param.manufacturerCode}, '%')
and m.model_code like CONCAT('%', #{param.modelCode}, '%')
and m.device_type = #{param.deviceType}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
and od.ord_status = #{param.orderStatus}
${param.dataScope} GROUP BY od.tenant_id, od.industry_code, od.device_code
order by distance,FIELD(m.device_status,'1','2','4','3','0'),od.device_code
order by FIELD(m.device_status,'1','2','4','3','0'),od.device_code
order by od.device_code
desc
asc
order by pro.area_code, city.area_code, county.area_code,od.device_code
)dt
dt.device_name like CONCAT('%', #{param.deviceName}, '%')
and ((dt.device_code like CONCAT('%', #{param.codeOrName}, '%')) or (dt.device_name like CONCAT('%', #{param.codeOrName}, '%')))

