select * from ( select distinct gg.dept_id as org_id, gg.dept_name as org_name, gg.dept_level as org_level, gg.parent_id as parent_org_id, m.device_code, m.site_code, m.device_status, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.longitude, m.latitude, concat(gg.dept_level + 1) AS devLevel, osd.ord_status as orderStatus, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from sys_dept gg LEFT JOIN vm_organ_device_rel_t dd ON gg.dept_id = dd.dept_id and dd.device_type = 12 and gg.industry_code = dd.industry_code LEFT JOIN vm_order_horn_devices osd ON dd.device_code = osd.device_code and dd.tenant_id = osd.tenant_id and dd.industry_code = osd.industry_code left join vm_horn_device_info_t m on m.device_code = osd.device_code left join vm_tenant_device_common_rel_t ten on ten.device_code = osd.device_code and ten.tenant_id = osd.tenant_id and ten.industry_code = osd.industry_code and ten.delete_flag = 0 and ten.device_type = 2 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '10' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and m.delete_flag = 0 and m.device_status != 4 and gg.del_flag = '0' AND dd.delete_flag = '0' and osd.tenant_id = #{param.tenantId} AND dd.device_code IS NOT NULL AND dd.device_code != ''
