mapper.select:
SELECT DISTINCT t2.site_code, t2.longitude, t2.latitude, t2.device_code as deviceCode, (case when length(IFNULL(tdr.device_name, '')) = 0 then t2.device_name else tdr.device_name end ) as device_name, t2.province_code, t2.city_code, t2.county_code, t2.town_code, t2.location, max(t2.height) as height, min(t2.device_status) as deviceStatus, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor FROM vm_order_horn_devices t1 left JOIN vm_horn_device_info_t t2 ON t1.device_code = t2.device_code left join vm_tenant_device_common_rel_t tdr on tdr.device_code = t1.device_code and tdr.tenant_id = t1.tenant_id and tdr.industry_code = t1.industry_code and tdr.delete_flag = 0 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = t2.device_code AND dct.coll_obj_type = '10' AND dct.user_id = #{param.userId}
INNER JOIN vm_device_labels_rel t3 ON t1.device_code = t3.device_code
LEFT JOIN vm_organ_device_rel_t dd ON t2.device_code = dd.device_code and dd.device_type = 12 and t1.industry_code = dd.industry_code
WHERE t2.delete_flag = '0' AND t1.delete_flag = '0' and t1.ord_status in (0,1,2) and t2.device_status != 4
AND t2.province_code = #{param.provinceCode}
AND t2.city_code = #{param.cityCode}
AND t2.county_code = #{param.countyCode}
AND t2.town_code = #{param.townCode}
and t3.label_id in
#{item}
AND dd.dept_id = #{param.deptId}
${param.dataScope} group by t2.site_code, t2.device_code

SELECT DISTINCT t2.site_code, t2.longitude, t2.latitude, t2.device_code as deviceCode, (case when length(IFNULL(tdr.device_name, '')) = 0 then t2.device_name else tdr.device_name end ) as device_name, t2.province_code, t2.city_code, t2.county_code, t2.town_code, max(t2.height) as height, min(t2.device_status) as deviceStatus, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor FROM vm_order_horn_devices t1 left JOIN vm_horn_device_info_t t2 ON t1.device_code = t2.device_code left join vm_tenant_device_common_rel_t tdr on tdr.device_code = t1.device_code and tdr.tenant_id = t1.tenant_id and tdr.industry_code = t1.industry_code and tdr.delete_flag = 0 and tdr.device_type = 2 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = t2.device_code AND dct.coll_obj_type = '10' AND dct.user_id = #{param.userId}
INNER JOIN vm_device_labels_rel t3 ON t1.device_code = t3.device_code
LEFT JOIN vm_organ_device_rel_t dd ON t2.device_code = dd.device_code and dd.device_type = 12 and t1.industry_code = dd.industry_code
WHERE t2.delete_flag = '0' and t2.device_status != 4 AND t1.delete_flag = '0' and t1.ord_status in (0,1,2)
AND t2.province_code = #{param.provinceCode}
AND t2.city_code = #{param.cityCode}
AND t2.county_code = #{param.countyCode}
AND t2.town_code = #{param.townCode}
and t3.label_id in
#{item}
AND dd.dept_id = #{param.deptId}
${param.dataScope} group by t2.site_code, t2.device_code

SELECT distinct m.device_code, osd.order_code, osd.tenant_id, m.manufacturer_code, (case when length(IFNULL(tdr.device_name, '')) = 0 then m.device_name else tdr.device_name end ) as device_name, m.province_code, m.city_code, m.county_code, m.town_code, m.site_code, m.latitude, m.longitude, m.location,
max(m.height) as height, min(m.device_status) as deviceStatus,
m.height, m.device_status,
(select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'broadcast_manufacturer' AND DICT_VALUE = m.manufacturer_code limit 1) manufacturerName, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor FROM vm_order_horn_devices osd left join vm_horn_device_info_t m on osd.device_code = m.device_code left join vm_tenant_device_common_rel_t tdr on tdr.device_code = osd.device_code and tdr.tenant_id = osd.tenant_id and tdr.industry_code = osd.industry_code and tdr.delete_flag = 0 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '10' AND dct.user_id = #{param.userId}
INNER JOIN vm_device_labels_rel t3 ON osd.device_code = t3.device_code
LEFT JOIN vm_organ_device_rel_t dd ON m.device_code = dd.device_code and dd.device_type = 12 and osd.industry_code = dd.industry_code
where osd.delete_flag = '0' and m.delete_flag = '0' and m.device_status != 4 and osd.ord_status in (0,1,2)
AND m.site_code = #{param.siteCode}
AND m.device_code = #{param.deviceCode}
AND m.province_code = #{param.provinceCode}
AND m.city_code = #{param.cityCode}
AND m.county_code = #{param.countyCode}
AND m.town_code = #{param.townCode}
and t3.label_id in
#{item}
AND dd.dept_id = #{param.deptId}
${param.dataScope}
group by m.site_code, m.device_code
group by m.device_code
order by m.height + 0 desc

select device_code, device_name, access_node, device_status as status from vm_horn_device_info_t
where delete_flag = 0 and device_code in

    #{item}
